32: /**
33:  * This React hook returns visit information if the patient UUID is not null. There are
34:  * potentially two relevant visits at a time: "active" and "current".
35:  *
36:  * The active visit is the most recent visit without an end date. The presence of an active
37:  * visit generally means that the patient is in the facility.
38:  *
39:  * The current visit is the active visit, unless a retrospective visit has been selected.
40:  * If there is no active visit and no selected retrospective visit, then there is no
41:  * current visit. If there is no active visit but there is a retrospective visit, then
42:  * the retrospective visit is the current visit. `currentVisitIsRetrospective` tells you
43:  * whether the current visit is a retrospective visit.
44:  *
45:  * The active visit and current visit require two separate API calls. `error` contains
46:  * the error from either one, if there is an error. `isValidating` is true if either
47:  * API call is in progress. `mutate` refreshes the data from both API calls.
48:  *
49:  * @param patientUuid Unique patient identifier `string`
50:  * @param representation The custom representation of the visit
51:  */
52: export function useVisit(patientUuid: string, representation = defaultVisitCustomRepresentation): VisitReturnType {
53:   // The callback we register has to exist before we read the store, but the mutate functions
54:   // it calls come from SWR calls that are keyed off what the store holds. Registering a stable
55:   // indirection through a ref breaks that cycle, so the store is read once per hook rather than
56:   // once to get the key and again to register.
57:   const mutateVisitRef = useRef<() => void>(undefined);
58:   const registeredMutateVisit = useCallback(() => mutateVisitRef.current?.(), []);
59:   const {
60:     patientUuid: visitStorePatientUuid,
